solutions.naive:
class Solution:
    def maximumUnits(self, boxTypes: list[list[int]], truckSize: int) -> int:
        boxes = []
        for count, units in boxTypes:
            boxes.extend([units] * count)
        boxes.sort(reverse=True)
        return sum(boxes[:truckSize])

solutions.better:
class Solution:
    def maximumUnits(self, boxTypes: list[list[int]], truckSize: int) -> int:
        total = 0
        for count, units in sorted(boxTypes, key=lambda item: item[1], reverse=True):
            take = min(count, truckSize)
            total += take * units
            truckSize -= take
            if truckSize == 0:
                break
        return total

solutions.optimal:
class Solution:
    def maximumUnits(self, boxTypes: list[list[int]], truckSize: int) -> int:
        max_units = 0
        for count, units in boxTypes:
            max_units = max(max_units, units)
        buckets = [0] * (max_units + 1)
        for count, units in boxTypes:
            buckets[units] += count
        total = 0
        for units in range(max_units, 0, -1):
            if buckets[units] == 0:
                continue
            take = min(buckets[units], truckSize)
            total += take * units
            truckSize -= take
            if truckSize == 0:
                break
        return total

